def name_operands(region,function_address,operation):
    if region=='Action' and function_address in FUNCTIONS:
        operation=operation.replace('CALL #C88C','CALL @Action.DivideSigned32To16.Entry')
        product=DETAILS[function_address][1]
        from ActionClipProductsData import RECORDS
        address=next(a for n,a in RECORDS if n==product)
        for offset,expression in ((0,'LowWord'),(1,'LowWord+1'),(2,'HighWord')):
            operation=operation.replace('(#'+format(address+offset,'04X')+')','(@ActionClipProductsData.'+product+'.'+expression+')')
        for address,expression in ((0xCF0B,'FirstPoint+FRenderProjectedPoint.Second'),(0xCF0D,'FirstPoint+FRenderProjectedPoint.First'),(0xCF1B,'SecondPoint+FRenderProjectedPoint.Second'),(0xCF1D,'SecondPoint+FRenderProjectedPoint.First')):
            operation=operation.replace('(#'+format(address,'04X')+')','(@ActionClipProductsState.'+expression+')')
        operation=operation.replace('(#9BA3)','(@ActionClipIntersectionsState.OutputSize)')
        operation=operation.replace('LD H, #90','LD H, @ActionClipIntersectionConst.OutputPage')
        operation=operation.replace('LD L, #FF','LD L, @ActionClipProductConst.SecondMaximum')
        operation=operation.replace('LD (HL), #5F','LD (HL), @ActionClipProductConst.FirstMaximum').replace('LD (HL), #FF','LD (HL), @ActionClipProductConst.SecondMaximum').replace('LD (HL), #00','LD (HL), @ActionClipProductConst.ZeroBound')
    for point in ('FirstPoint','SecondPoint'):
        operation=operation.replace('@ActionClipProductsState.'+point+'+FRenderProjectedPoint.','@ActionClipPoints.'+point+'.')
    return operation
